public class NotenException(string msg)
  : Exception(msg);

public class UngueltigeNoteException(int note)
  : NotenException($"Note {note} nicht in 1-5")
{
  public int Note { get; } = note;
}

public static class Noten
{
  public static double Schnitt(
    IReadOnlyList<int> noten)
  {
    ArgumentNullException.ThrowIfNull(noten);
    if (noten.Count == 0)
      throw new ArgumentException(
        "noten ist leer", nameof(noten));
    foreach (var n in noten)
      if (n is < 1 or > 5)
        throw new UngueltigeNoteException(n);
    return noten.Average();
  }

  public static bool TrySchnitt(
    IReadOnlyList<int> noten, out double s)
  {
    s = 0;
    if (noten is not { Count: > 0 } ||
        noten.Any(n => n is < 1 or > 5))
      return false;
    s = noten.Average();
    return true;
  }
}

try
{
  Noten.Schnitt([1, 7]);
}
catch (NotenException e)
{
  Console.WriteLine($"{e.Message} | " +
    (e as UngueltigeNoteException)?.Note);
}
// Note 7 nicht in 1-5 | 7

if (Noten.TrySchnitt([1, 2], out var s))
  Console.WriteLine(s);   // 1.5

public static class NotenAlt
